import 'package:flutter/widgets.dart';
import 'package:flutter_svg/flutter_svg.dart';

/// The Caskly app icon (cocktail glass) as used inside the app. Same SVG
/// masters as the desktop icon (assets/branding/, generated by
/// tooling/brand/make_svgs.py): the bold simplified glass at small sizes,
/// the detailed one above 48 px.
class CasklyLogo extends StatelessWidget {
  const CasklyLogo({super.key, this.size = 36});

  final double size;

  @override
  Widget build(BuildContext context) {
    final asset = size <= 48 ? 'assets/branding/caskly_icon_small.svg' : 'assets/branding/caskly_icon_win.svg';
    return SvgPicture.asset(asset, width: size, height: size, semanticsLabel: 'Caskly');
  }
}
